action.code:
uint64_t result = 0;
    int shift = 0;
    while (true) {
        if (input->size() < 1) {
            return false; // Not enough data to read a byte
        }
        uint8_t byte = (*input)[0];
        input->remove_prefix(1); // Advance the slice
        result |= static_cast<uint64_t>(byte & 0x7F) << shift;
        if ((byte & 0x80) == 0) {
            break; // Most significant bit is 0, this is the last byte
        }
        shift += 7;
        if (shift >= 64) {
            return false; // Varint is too long
        }
    }
    *value = result;
    return true;

